: > "$LOG"

log() {
  printf '%s %s\n' "$(date -u +%FT%TZ)" "$*" | tee -a "$LOG"
}

run_cmd() {
  local label="$1"
  shift
  log "START $label"
  "$@"
  local rc=$?
  log "DONE $label rc=$rc"
  return "$rc"
}

put_script() {
  local host="$1"
  local local_name="$2"
  local remote_path="$3"
  local log_name="$4"
  run_cmd "put_${host}_${local_name}" \
    python3 "$SCP_PUT" \
      --host "$host" \
      --local "$ART/$local_name" \
      --remote "$remote_path" \
      --out "$ART/$log_name" \
      --timeout 120
}

