OVERALL_RC=0
GATE_RC=1
LATE_GATE_RC=1
TX_SUMMARY_GATE_RC=1
STOP_SUMMARY_GATE_RC=1
UE_STARTED=0
START_RC=1

run_or_note() {
  local label="$1"
  shift
  run_cmd "$label" "$@"
  local rc=$?
  if [ "$rc" -ne 0 ]; then
    log "STEP_FAILED label=$label rc=$rc"
    OVERALL_RC=1
  fi
  return "$rc"
}

