UE_PRACH_SYNC_GUARD_SLOTS' PAVONIS_SRSUE_PRACH_SYNC_GUARD_TRACE=1 PAVONIS_SRSUE_PRACH_DEFER_MS='$UE_PRACH_DEFER_MS' PAVONIS_SRSUE_CAMPING_TTI_TRACE=1 PAVONIS_SRSUE_CAMPING_TTI_ALIGN=1 PAVONIS_RF_BLADE_FORCE_HIGH_PEAK_SOB=0 PAVONIS_RF_BLADE_FORCE_HIGH_PEAK_EOB=0 PAVONIS_RF_BLADE_HIGH_PEAK_EOB_THEN_SOB=0 PAVONIS_RF_BLADE_PRACH_BURST_ONLY=1 PAVONIS_RF_BLADE_TX_DBG_RESTART_TX_STREAM_ON_FIRST_HIGH_PEAK=1 PAVONIS_RF_BLADE_STATE_DBG=1 PAVONIS_RF_BLADE_STATE_DBG_MAX_LINES=500 PAVONIS_RF_BLADE_STATE_DBG_GET_TIME_FIRST=40 PAVONIS_RF_BLADE_STATE_DBG_GET_TIME_EVERY=256 @REMOTE_HOME@/stage6_cp1660_ue.sh"
    UE_STARTED=1

    if [ "$PAVONIS_SOAPY_RX_APPEND_ENABLE" = "1" ] && [ "$PAVONIS_SOAPY_RX_APPEND_ARM_MODE" = "after_sib1" ]; then
