        --host ue \
        --out "$ART/cp1733_${STAMP}_sens_wait_sib1_late_rx_append_arm.log" \
        --timeout "$LATE_ARM_SSH_TIMEOUT" \
        -- bash -lc "${ENV_PREFIX} set -u; date -u --iso-8601=ns; OUT=''; for j in \$(seq 1 80); do OUT=\$(ls -td \"\$SENS_BASE\"/run_* 2>/dev/null | head -1 || true); if [ -n \"\$OUT\" ] && [ -f \"\$OUT/launch.env\" ]; then break; fi; sleep 0.05; done; echo OUT=\"\$OUT\"; test -n \"\$OUT\" || exit 20; UE_STDOUT=\$(awk -F= '/^UE_STDOUT=/{print \$2}' \"\$OUT/launch.env\" 2>/dev/null | tail -1); if [ -z \"\$UE_STDOUT\" ]; then UE_STDOUT=\$(find \"\$OUT\" -maxdepth 1 -name 'srsue.stdout.log' -print -quit 2>/dev/null || true); fi; echo UE_STDOUT=\"\$UE_STDOUT\"; test -n \"\$UE_STDOUT\" || exit 21; deadline=\$((SECONDS + $PAVONIS_SOAPY_RX_LATE_ARM_TIMEOUT_SEC)); while [ \"\$SECONDS\" -lt \"\$deadline\" ]; do if [ -s \"\$UE_STDOUT\" ] && grep -Eq 'PAVONIS_SRSUE_SIB1_TRACE event=phy_set_config_ok|PAVONIS_SRSUE_PRACH_CFG transmitted|PRACH-TX' \"\$UE_STDOUT\"; then echo LATE_ARM_TRIGGER_UTC=\$(date -u --iso-8601=ns); grep -En 'PAVONIS_SRSUE_SIB1_TRACE event=phy_set_config_ok|PAVONIS_SRSUE_PRACH_CFG transmitted|PRACH-TX' \"\$UE_STDOUT\" | head -5; exit 0; fi; if [ -s \"\$OUT/result.env\" ] && grep -q '^END_UTC=' \"\$OUT/result.env\"; then echo UE_DONE_BEFORE_LATE_ARM; cat \"\$OUT/result.env\"; exit 42; fi; sleep '$PAVONIS_SOAPY_RX_LATE_ARM_POLL_SEC'; done; echo LATE_ARM_TIMEOUT; [ -s \"\$UE_STDOUT\" ] && tail -80 \"\$UE_STDOUT\" || true; exit 43"
