run_or_note parse_cp1660_summary python3 - "$SUMMARY_JSON" "$LOCAL_NUC4_DIR" "$LOCAL_SENS_DIR" "$LOG" "$HOST_STATE_NUC4_LOG" "$HOST_STATE_SENS_LOG" <<'PY'
import json
import re
import sys
from pathlib import Path

out = Path(sys.argv[1])
ran_dir = Path(sys.argv[2])
sens_dir = Path(sys.argv[3])
sequence_log = Path(sys.argv[4])
host_state_ran_log = Path(sys.argv[5])
host_state_sens_log = Path(sys.argv[6])

def read(path):
    try:
        return path.read_text(errors="replace")
    except Exception:
        return ""

def parse_last_summary(text, prefix):
    line = next((line for line in reversed(text.splitlines()) if line.startswith(prefix)), "")
    fields = {}
    for token in line.split():
        if "=" not in token:
            continue
        key, value = token.split("=", 1)
        if re.fullmatch(r"-?\d+", value):
            fields[key] = int(value)
        else:
            fields[key] = value
    return fields

def find_one(root, pattern):
    if not root.exists():
        return None
    matches = sorted(root.rglob(pattern), key=lambda p: (len(str(p)), str(p)))
    return matches[0] if matches else None

def count_pat(text, pattern):
    return len(re.findall(pattern, text))

def count_stage1_selected(text):
    selected = 0
    lines = text.splitlines()
    if not lines:
        return selected
    header = lines[0].split("\t")
    try:
        selected_idx = header.index("selected")
    except ValueError:
        selected_idx = 10
    for line in lines[1:]:
        fields = line.split("\t")
        if len(fields) > selected_idx and fields[selected_idx] == "1":
            selected += 1
    return selected

def parse_kv_tokens(line):
    fields = {}
    for token in line.strip().split():
        if "=" in token:
            key, value = token.split("=", 1)
            fields[key] = value
    return fields

def int_or_none(value):
    try:
        return int(value)
    except Exception:
        return None

def parse_host_state_log(path):
    text = read(path)
    summary_row = {}
    cpus = []
    thermal = []
    usb_bladerf = []
    for line in text.splitlines():
        if "PAVONIS_HOST_STATE cpu " in line:
            cpus.append(parse_kv_tokens(line))
        elif "PAVONIS_HOST_STATE thermal " in line:
            thermal.append(parse_kv_tokens(line))
        elif "PAVONIS_HOST_STATE usb_bladerf " in line:
            usb_bladerf.append(parse_kv_tokens(line))
        elif "PAVONIS_HOST_STATE summary " in line:
            summary_row = parse_kv_tokens(line)
    governors = sorted({row.get("governor", "") for row in cpus if row.get("governor")})
    epps = sorted({row.get("epp", "") for row in cpus if row.get("epp")})
    return {
        "path": str(path),
        "present": path.exists(),
        "host": summary_row.get("host"),
        "role": summary_row.get("role"),
        "mode": summary_row.get("mode"),
        "power_profile": summary_row.get("power_profile"),
        "governor_total": int_or_none(summary_row.get("governor_total")),
        "governor_bad": int_or_none(summary_row.get("governor_bad")),
        "governor_all_performance": summary_row.get("governor_all_performance") == "1",
        "epp_total": int_or_none(summary_row.get("epp_total")),
        "epp_bad": int_or_none(summary_row.get("epp_bad")),
        "epp_all_performance": summary_row.get("epp_all_performance") == "1",
        "thermal_count": int_or_none(summary_row.get("thermal_count")),
        "thermal_max_millic": int_or_none(summary_row.get("thermal_max_millic")),
        "thermal_max_type": summary_row.get("thermal_max_type"),
        "min_cur_khz": int_or_none(summary_row.get("min_cur_khz")),
        "max_cur_khz": int_or_none(summary_row.get("max_cur_khz")),
        "max_limit_khz": int_or_none(summary_row.get("max_limit_khz")),
        "m2sdr_power": summary_row.get("m2sdr_power"),
        "m2sdr_pcie_speed": summary_row.get("m2sdr_pcie_speed"),
        "m2sdr_pcie_width": summary_row.get("m2sdr_pcie_width"),
        "bladerf_usb_present_count": int_or_none(summary_row.get("bladerf_usb_present_count")),
        "bladerf_usb_power_bad": int_or_none(summary_row.get("bladerf_usb_power_bad")),
        "bladerf_usb_power_controls": summary_row.get("bladerf_usb_power_controls"),
        "bladerf_usb_runtime_statuses": summary_row.get("bladerf_usb_runtime_statuses"),
        "bladerf_usb_autosuspends": summary_row.get("bladerf_usb_autosuspends"),
        "bladerf_usb_speeds": summary_row.get("bladerf_usb_speeds"),
        "bladerf_usb_authorized": summary_row.get("bladerf_usb_authorized"),
        "governors": governors,
        "epps": epps,
        "cpu_rows": len(cpus),
        "thermal_rows": len(thermal),
        "usb_bladerf_rows": usb_bladerf,
    }

def parse_order_trace(text):
    event_re = re.compile(r"PAVONIS_PUXCH_ORDER_TRACE event=(\S+)(.*)")
    token_re = re.compile(r"([A-Za-z0-9_]+)=([^ ]+)")
    events = []
    counts = {}
    for line in text.splitlines():
        m = event_re.search(line)
        if not m:
            continue
        event_name = m.group(1)
        fields = dict(token_re.findall(m.group(2)))
        fields["event"] = event_name
        fields["steady_ns_int"] = int_or_none(fields.get("steady_ns"))
        fields["system_slot_int"] = int_or_none(fields.get("system_slot"))
        fields["symbol_int"] = int_or_none(fields.get("symbol", fields.get("alloc_end")))
        events.append(fields)
        counts[event_name] = counts.get(event_name, 0) + 1
    grid_by_slot_symbol = {}
    for event in events:
        if event.get("event") == "puxch_grid_symbol_written":
            key = (event.get("system_slot_int"), event.get("symbol_int"))
            if key[0] is not None and key[1] is not None:
                grid_by_slot_symbol[key] = event
    judgments = []
    bad = 0
    unknown = 0
    for event in events:
        if event.get("event") != "upper_pusch_task_start":
            continue
        alloc_end = int_or_none(event.get("alloc_end"))
        key = (event.get("system_slot_int"), alloc_end)
        grid = grid_by_slot_symbol.get(key)
        ok = None
        delta_ns = None
        if grid and grid.get("steady_ns_int") is not None and event.get("steady_ns_int") is not None:
            delta_ns = event["steady_ns_int"] - grid["steady_ns_int"]
            ok = delta_ns >= 0
        else:
            unknown += 1
        if ok is False:
            bad += 1
        judgments.append({
            "system_slot": event.get("system_slot"),
            "slot": event.get("slot"),
            "rnti": event.get("rnti"),
            "harq": event.get("harq"),
            "alloc_end": event.get("alloc_end"),
            "grid_before_task_start": ok,
            "grid_to_task_start_delta_ns": delta_ns,
        })
    return {
        "event_counts": counts,
        "grid_symbol_written_count": counts.get("puxch_grid_symbol_written", 0),
        "task_start_count": counts.get("upper_pusch_task_start", 0),
        "task_start_without_grid_judgment": unknown,
        "grid_after_task_start_count": bad,
        "all_judged_task_starts_grid_before_task_start": bool(judgments) and bad == 0 and unknown == 0,
        "judgments": judgments[:32],
    }

