        ) if ran_dir.exists() else 0,
        "puxch_target_raw_cf32": len(list(ran_dir.rglob("pavonis_puxch_target_*.cf32"))) if ran_dir.exists() else 0,
        "pucch_f1_grid_cf32": len(list(ran_dir.rglob("pavonis_pucch_f1_grid_*.cf32"))) if ran_dir.exists() else 0,
        "soapy_rx_append_cf32": len(list(ran_dir.rglob("pavonis_soapy_rx_append*.cf32"))) if ran_dir.exists() else 0,
        "soapy_rx_raw_cf32": len([
            p for p in ran_dir.rglob("pavonis_soapy_rx_*.cf32")
            if "pavonis_soapy_rx_append" not in p.name
        ]) if ran_dir.exists() else 0,
        "rf_blade_tx_dbg_sc16": len(list(sens_dir.rglob("pavonis_rf_blade_tx_dbg_*.sc16"))) if sens_dir.exists() else 0,
        "rf_blade_tx_dbg_meta": len(list(sens_dir.rglob("pavonis_rf_blade_tx_dbg_*.meta.txt"))) if sens_dir.exists() else 0,
    },
    "first_failed_stage": first_failed_stage,
}
out.write_text(json.dumps(summary, indent=2, sort_keys=True) + "\n")
print(json.dumps(summary, indent=2, sort_keys=True))
PY

